14	//! A wrapper around any Read to treat it as an RNG.
15	
16	use std::fmt;
17	use std::io::Read;
18	
19	use rand_core::{impls, Error, RngCore};
20	
21	/// An RNG that reads random bytes straight from any type supporting
22	/// [`std::io::Read`], for example files.
23	///
24	/// This will work best with an infinite reader, but that is not required.
25	///
26	/// This can be used with `/dev/urandom` on Unix but it is recommended to use
27	/// [`OsRng`] instead.
28	///
29	/// # Panics
30	///
31	/// `ReadRng` uses [`std::io::Read::read_exact`], which retries on interrupts.
32	/// All other errors from the underlying reader, including when it does not
33	/// have enough data, will only be reported through [`try_fill_bytes`].
34	/// The other [`RngCore`] methods will panic in case of an error.
35	///
36	/// [`OsRng`]: rand::rngs::OsRng
37	/// [`try_fill_bytes`]: RngCore::try_fill_bytes
38	#[derive(Debug)]
39	pub struct ReadRng<R> {
40	    reader: R,
41	}
42	
43	impl<R: Read> ReadRng<R> {
44	    /// Create a new `ReadRng` from a `Read`.
45	    pub fn new(r: R) -> Self {
46	        Self { reader: r }
47	    }
48	}
49	
50	impl<R: Read> RngCore for ReadRng<R> {
51	    fn next_u32(&mut self) -> u32 {
52	        impls::next_u32_via_fill(self)
53	    }
54	
55	    fn next_u64(&mut self) -> u64 {
56	        impls::next_u64_via_fill(self)
57	    }
58	
59	    fn fill_bytes(&mut self, dest: &mut [u8]) {
60	        self.try_fill_bytes(dest).unwrap_or_else(|err| {
61	            panic!("reading random bytes from Read implementation failed; error: {err}");
62	        });
63	    }
64	
65	    fn try_fill_bytes(&mut self, dest: &mut [u8]) -> Result<(), Error> {
66	        if dest.is_empty() {
67	            return Ok(());
68	        }
69	        // Use `std::io::read_exact`, which retries on `ErrorKind::Interrupted`.
70	        self.reader
71	            .read_exact(dest)
72	            .map_err(|e| Error::new(ReadError(e)))
73	    }
74	}
75	
76	/// `ReadRng` error type
77	#[derive(Debug)]
78	pub struct ReadError(std::io::Error);
79	
80	impl fmt::Display for ReadError {
81	    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
82	        write!(f, "ReadError: {}", self.0)
83	    }
84	}
85	
86	impl std::error::Error for ReadError {
87	    fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {
88	        Some(&self.0)
89	    }
90	}
91	
92	#[cfg(test)]
93	mod test {
94	    use std::println;
95	
96	    use super::ReadRng;
97	    use rand::RngCore;
98	
99	    #[test]
100	    fn test_reader_rng_u64() {
101	        // transmute from the target to avoid endianness concerns.
102	        #[rustfmt::skip]
103	        let v = [0u8, 0, 0, 0, 0, 0, 0, 1,
104	                 0,   4, 0, 0, 3, 0, 0, 2,
105	                 5,   0, 0, 0, 0, 0, 0, 0];
106	        let mut rng = ReadRng::new(&v[..]);
107	
108	        assert_eq!(rng.next_u64(), 1 << 56);
109	        assert_eq!(rng.next_u64(), (2 << 56) + (3 << 32) + (4 << 8));
110	        assert_eq!(rng.next_u64(), 5);
111	    }
112	
113	    #[test]
114	    fn test_reader_rng_u32() {
115	        let v = [0u8, 0, 0, 1, 0, 0, 2, 0, 3, 0, 0, 0];
116	        let mut rng = ReadRng::new(&v[..]);
117	
118	        assert_eq!(rng.next_u32(), 1 << 24);
119	        assert_eq!(rng.next_u32(), 2 << 16);
120	        assert_eq!(rng.next_u32(), 3);
121	    }
122	
123	    #[test]
124	    fn test_reader_rng_fill_bytes() {
125	        let v = [1u8, 2, 3, 4, 5, 6, 7, 8];
126	        let mut w = [0u8; 8];
127	
128	        let mut rng = ReadRng::new(&v[..]);
129	        rng.fill_bytes(&mut w);
130	
131	        assert!(v == w);
132	    }
133	
134	    #[test]
135	    fn test_reader_rng_insufficient_bytes() {
136	        let v = [1u8, 2, 3, 4, 5, 6, 7, 8];
137	        let mut w = [0u8; 9];
138	
139	        let mut rng = ReadRng::new(&v[..]);
140	
141	        let result = rng.try_fill_bytes(&mut w);
142	        assert!(result.is_err());
143	        println!("Error: {}", result.unwrap_err());
144	    }
145	}
